#!/usr/bin/env python3
from pathlib import Path
from html import escape
R=Path(__file__).resolve().parents[1]; B='2026-09-03-visual-fix'
CSS='''*{box-sizing:border-box}html{background:#05040a;color:#fff;font-family:system-ui,sans-serif}body{margin:0;background:radial-gradient(circle at top,#18082a,#05040a 42%);min-height:100vh}.nav{position:sticky;top:0;z-index:10;display:flex;gap:10px;overflow-x:auto;padding:12px 16px;background:#05050bee;border-bottom:1px solid #532a75}.nav a{flex:0 0 auto;color:#fff;text-decoration:none;font-weight:800;padding:11px 15px;border:1px solid #36313d;border-radius:16px;background:#0a0910}.nav .brand{color:#45bfff}.shell{max-width:1120px;margin:auto;padding:18px 16px 60px}.hero,.section{border:1px solid #3c2b49;border-radius:24px;background:#0b0810;margin-bottom:22px;overflow:hidden}.hero{display:grid;grid-template-columns:1.15fr .85fr}.hero img{width:100%;height:100%;max-height:72vh;object-fit:contain;background:#020205}.copy,.section{padding:26px}.ey{letter-spacing:.16em;text-transform:uppercase;font-weight:900;color:#cdbbd9}.hero h1,.section h2{font-size:clamp(2rem,5vw,4rem);line-height:1.02;margin:.25em 0}.copy p,.section p{color:#c9c1d3;font-size:1.08rem;line-height:1.55}.btns{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.btn{padding:12px 16px;border-radius:14px;background:linear-gradient(135deg,#7c3aed,#2563eb);border:1px solid #8b5cf6;color:#fff;text-decoration:none;font-weight:900}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.card{display:block;color:#fff;text-decoration:none;border:1px solid #5b377d;border-radius:20px;overflow:hidden;background:#100a17}.card img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#020205}.card b,.card span{display:block;padding:0 16px}.card b{font-size:1.2rem;padding-top:15px}.card span{color:#c5bacd;padding-top:6px}.card i{display:block;padding:14px 16px 17px;color:#62c7ff;font-style:normal;font-weight:900}.chips{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.chip{display:block;color:#fff;text-decoration:none;border:1px solid #4b3a55;border-radius:18px;padding:18px;background:#0f0b13;font-weight:900}.mission{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.mission a{color:#fff;text-decoration:none;border:1px solid #653e96;border-radius:18px;padding:18px;background:linear-gradient(145deg,#211333,#0b0810)}.mission em{display:block;font-style:normal;font-size:2rem}.mark{display:flex;align-items:center;justify-content:center;min-height:350px;text-align:center;font-size:clamp(3rem,10vw,7rem);font-weight:900;background:radial-gradient(circle,#2b1243,#09070f 60%)}.law{color:#f6c85b}.impact{color:#77ed71;flex-direction:column}.impact small{font-size:.25em;letter-spacing:.15em}.tokens{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.token{color:#fff;text-decoration:none;border:1px solid #6d38a4;border-radius:16px;padding:14px;background:#0f0816}.hope img{width:100%;display:block;max-height:72vh;object-fit:contain;background:#020205}.foot{text-align:center;color:#948b9a;padding:25px}@media(max-width:820px){.hero{grid-template-columns:1fr}.grid,.mission{grid-template-columns:repeat(2,1fr)}.chips{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.tokens{grid-template-columns:repeat(2,1fr)}}@media(max-width:460px){.grid,.mission,.tokens{grid-template-columns:1fr}}'''
def w(path,text):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def style(site):w(f'{site}/visual-fix.css',CSS)
def page(title,nav,body):
 n=''.join(f'<a class="{"brand" if i==0 else ""}" href="{u}">{escape(t)}</a>' for i,(t,u) in enumerate(nav))
 return f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><link rel="stylesheet" href="/visual-fix.css"></head><body data-oneworldz-build="{B}"><nav class="nav">{n}</nav><main class="shell">{body}</main><div class="foot">OneWorldz 🌐 One Vision • Helping the People Who Help People</div></body></html>'
