 w(f'oneworldz.com/heroes/{s}/index.html',page(f'{n} | OneWorldz',[('OneWorldz','/'),('Heroes','/heroes/'),(n,f'/heroes/{s}/')],f'<section class="hero"><img src="{img}" alt="Approved OneWorldz artwork"><div class="copy"><p class="ey">OneWorldz Hero</p><h1>{escape(n)}</h1><p>Permanent profile route for public work centred on helping people directly. No fabricated partnership or endorsement is claimed.</p></div></section>'))
