for n,d in chains:
 style(d); b=f'<section class="hero"><img src="/hero.png" alt="Approved {n} artwork"><div class="copy"><p class="ey">CryptoWorldz</p><h1>{n}</h1><p>Dedicated blockchain destination. Navigation returns to CryptoWorldz Central.</p><div class="btns"><a class="btn" href="https://cryptoworldz.xyz">CryptoWorldz Central</a><a class="btn" href="/learn/">Learn</a></div></div></section>'
 w(f'{d}/index.html',page(f'{n} | CryptoWorldz',[(n,'/'),('CryptoWorldz','https://cryptoworldz.xyz'),('Learn','/learn/'),('Community','/community/')],b))
