t=[('Original PDC','PDC'),('First PDC1','PDC1'),('Later PDC1','PDC1'),('Limited Edition','PDCLE'),('Zed','ZED'),('Grace','GRACE'),('A.U.T.O.','AUTO'),('G','G'),('Robin Hood','RHL'),('SolCat','SOLCAT')]
