pb=f'<section class="section hope"><p class="ey">OneWorldz Hope Chest 1927</p><h1>Hope Chest first.</h1><img src="/hero.png" alt="Approved Hope Chest 1927 artwork"><p>Nothing covers the approved artwork.</p></section><section class="section"><h2>10 genuine legacy records</h2><div class="tokens">{ti}</div></section><section class="section"><img src="/action-team.png" alt="PDC action artwork" style="width:100%;max-height:650px;object-fit:contain"></section>'
